Local Ltac simpl_sizes ::=
  rewrite ?length_app;
  repeat match goal with
  | |- context [Z.of_nat (cells_size ?cs)] =>
      let v := eval cbv in (Z.of_nat (cells_size cs)) in
      lazymatch v with Z0 => idtac | Zpos _ => idtac end;
      change (Z.of_nat (cells_size cs)) with v
  end;
  cbn [cells_size csize length cbytes Nat.add Z.of_nat Pos.of_succ_nat Pos.succ];
  rewrite ?length_le8, ?length_le4, ?length_le2, ?length_le1, ?length_app; cbn [length].
