Lemma pf_L2_all : forall n, PF_L2_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros p. intros until g. intros CTX PURE BSZ TMP24 N1 NP PL MEAS. exfalso. cbn in MEAS. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply pf_L2_step. exact IH.
Qed.

End HCW.
